class FunziApi{static final _f=FirebaseFunctions.instance;static Future<Map<String,dynamic>> _call(String name,[Map<String,dynamic>? data])async{final r=await _f.httpsCallable(name).call(data??{});return Map<String,dynamic>.from(r.data as Map);}static Future<Map<String,dynamic>> quiz(String skillId,[int count=5])=>_call('generateQuiz',{'skillId':skillId,'count':count});static Future<Map<String,dynamic>> flashcards(String skillId,[int count=10])=>_call('generateFlashcards',{'skillId':skillId,'count':count});static Future<Map<String,dynamic>> quests()=>_call('generateQuests',{});static Future<Map<String,dynamic>> scienceSimulation(String skillId,String topic)=>_call('generateScienceSimulation',{'skillId':skillId,'topic':topic,'subject':'Integrated Science','difficulty':'standard'});static Future<Map<String,dynamic>> submitPortfolio(Map<String,dynamic> e)=>_call('submitPortfolioEvidence',e);static Future<Map<String,dynamic>> bootstrapAdmin()=>_call('bootstrapPlatformAdmin',{});static Future<Map<String,dynamic>> adminDashboard()=>_call('adminGetDashboard',{});static Future<Map<String,dynamic>> adminSettings(Map<String,dynamic>x)=>_call('adminUpdateSettings',x);static Future<Map<String,dynamic>> adminProviderKey(Map<String,dynamic>x)=>_call('adminSetProviderKey',x);static Future<Map<String,dynamic>> adminDeleteKey(String id)=>_call('adminDeleteProviderKey',{'id':id});static Future<Map<String,dynamic>> adminUserRole(String uid,String role)=>_call('adminSetUserRole',{'uid':uid,'role':role});static Future<Map<String,dynamic>> tutor(String message,{String? skillId})=>_call('tutor',{'message':message,'skillId':skillId});static Future<Map<String,dynamic>> saveNotebook(Map<String,dynamic> n)=>_call('saveLabNotebook',n);static Future<Map<String,dynamic>> submitNotebook(String id)=>_call('submitLabNotebook',{'notebookId':id});static Future<Map<String,dynamic>> issueChallenge(String labId,String kind)=>_call('issueLabChallenge',{'labId':labId,'kind':kind});static Future<Map<String,dynamic>> verifyChallenge(String id,Object answer)=>_call('verifyLabChallenge',{'challengeId':id,'answer':answer});static Future<Map<String,dynamic>> route(String skillId,{int minutes=30,bool lowBandwidth=false})=>_call('learningExperienceRoute',{'skillId':skillId,'minutes':minutes,'lowBandwidth':lowBandwidth});static Future<Map<String,dynamic>> adaptive(String skillId,String mode)=>_call('generateAdaptiveExperience',{'skillId':skillId,'mode':mode});static Future<Map<String,dynamic>> createLabSession(String labId)=>_call('createLabSession',{'labId':labId});static Future<Map<String,dynamic>> joinLabSession(String sessionId,String role)=>_call('joinLabSession',{'sessionId':sessionId,'role':role});static Future<Map<String,dynamic>> ingestSensorSamples(String notebookId,String adapterId,List<Map<String,dynamic>> samples)=>_call('ingestSensorSamples',{'notebookId':notebookId,'adapterId':adapterId,'samples':samples});}
